SourceCode.Declaration:
/// <summary>
/// Class for daily consolidation of MET Customer MDF Calculation Transactions
/// </summary>
public class METCustomerMDFConsolidation_Daily extends METCustomerMDFConsolidation
{
    TransDate shipDate;

}

Method.Source:
/// <summary>
/// Parameter method for ship date
/// </summary>
/// <param name = "_shipDate">TransDate</param>
/// <returns>TransDate</returns>
public TransDate parmShipDate(TransDate _shipDate = shipDate)
{
    shipDate = _shipDate;

    return shipDate;
}

/// <summary>
/// Get the query for fetching METCustomerMDFCalculationTrans records filtered by ship date
/// </summary>
/// <returns>Query</returns>
public Query getQuery()
{
    return new Query(querystr(METCustomerMDFCalculationSumQuery_Dialy));
}

/// <summary>
/// Update the query to filter by ship date
/// </summary>
/// <param name = "_query">Query</param>
/// <returns>Query</returns>
Query updateQuery(Query _query)
{
    Query ret = super(_query);

    QueryBuildDataSource qbds = ret.dataSourceTable(tableNum(METCustomerMDFCalculationTrans));

    qbds.addRange(fieldNum(METCustomerMDFCalculationTrans, ShipDate)).value(queryValue(shipDate));

    return ret;
}

/// <summary>
/// Update METCustomerMDFCalculationTrans records to link them to the created consolidation record
/// </summary>
/// <param name = "_calculationTransSum">METCustomerMDFCalculationTrans</param>
/// <param name = "_consolidationTableRecId">RefRecId</param>
public void updateCalculationTrans(METCustomerMDFCalculationTrans _calculationTransSum, RefRecId _consolidationTableRecId)
{
    METCustomerMDFCalculationTrans calculationTransUpdate;

    update_recordset calculationTransUpdate
        setting CustomerMDFConsolidationTable = _consolidationTableRecId
        where calculationTransUpdate.CustAccount == _calculationTransSum.CustAccount
           && calculationTransUpdate.SiteId == _calculationTransSum.SiteId
           && calculationTransUpdate.Warehouse == _calculationTransSum.Warehouse
           && calculationTransUpdate.CustomerMDFSetupTable == _calculationTransSum.CustomerMDFSetupTable
           && calculationTransUpdate.CustomerMDFConsolidationTable == 0
           && calculationTransUpdate.ShipDate == _calculationTransSum.ShipDate;
}
